function head(t,st){const done=st.done?.length||0,pct=Math.round(done/Math.max(1,t.items.length)*100);return `<section class="l8-card l8-task-head"><div class="l8-task-title-block"><span class="l8-task-kicker">Aufgabe ${taskNo(t)}</span><h1>${esc(t.title)}</h1><p>${esc(t.icon||'✅')} ${esc(t.instruction||'')}</p></div><div class="l8-progress-row"><span>${done} von ${t.items.length} fertig</span><strong>${pct}%</strong></div><div class="l8-progress"><div style="width:${pct}%"></div></div></section>`}
